import{_ as a,C as r,o as n,c as s,ag as i,E as o}from"./chunks/framework.DLWhSH9p.js";const f=JSON.parse('{"title":"Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md"}'),l={name:"guide/index.md"};function d(c,e,h,p,u,g){const t=r("SchemeImage");return n(),s("div",null,[e[0]||(e[0]=i('<h1 id="getting-started" tabindex="-1">Getting Started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting Started&quot;">​</a></h1><p>CRAFT Studio is a YouTube content creation platform with AI-powered idea generation, script writing, video production, audio, competitive research, and multi-source resource discovery — orchestrated by specialized AI agents that collaborate through a 7-stage pipeline.</p><h2 id="what-you-can-do" tabindex="-1">What You Can Do <a class="header-anchor" href="#what-you-can-do" aria-label="Permalink to &quot;What You Can Do&quot;">​</a></h2><ul><li><strong>Generate Ideas</strong> — AI-powered brainstorming with channel personality, or save from YouTube research</li><li><strong>Write Scripts</strong> — AI writes, revises, and polishes with fact-checking and humanization</li><li><strong>Produce Videos</strong> — a guided pipeline that takes you from idea to rendered MP4</li><li><strong>Research Competitors</strong> — YouTube search with outlier detection, channel deep dives, and earnings estimates</li><li><strong>Curate Content</strong> — AI-scored proposals, approval workflows, and episode pipeline tracking</li><li><strong>Produce Audio</strong> — 300+ voices with screenplay-aware parsing and voice cloning</li><li><strong>Find Resources</strong> — Search 14 royalty-free sources for video, image, audio, and reference material</li><li><strong>Collaborate</strong> — invite editors, video editors, and voice actors per channel; review notes pin to the timeline</li><li><strong>Go Mobile</strong> — Android companion app with full dashboard parity</li></ul>',4)),o(t,{name:"top-bar",alt:"Studio sidebar — Mossworks logo, Studio section with channel selector and stage links"}),o(t,{name:"episodes-panel",alt:"Episodes kanban — every show is a card moving across the pipeline"}),o(t,{name:"channel-dive",alt:"Channel Deep Dive"}),e[1]||(e[1]=i('<h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The Studio is organised around a single <strong>left sidebar</strong> that holds every entry point. In it:</p><ul><li><strong>Mossworks logo</strong> — pin the sidebar open or let it collapse to a rail of icons.</li><li><strong>Home</strong> — the marketing landing for your account.</li><li><strong>Studio</strong> — expands to show your channel selector, channel settings, and the workflow stages: <code>Episodes → Proposals → Discover → Scripts → Storyboard → Composition → Audio → Publish</code>. Proposals appears for premium accounts.</li><li><strong>Marketplace</strong> — jump to the creator marketplace.</li><li><strong>Search (⌘K)</strong> — opens the command palette.</li><li><strong>Profile</strong> at the bottom — your account menu (Teams, Billing &amp; plan, API keys, Notifications, Theme &amp; colors, Feedback, Documentation, Sign out).</li></ul><p>Episodes is the single backlog: Proposals → &quot;Create Episode&quot; and Discover → &quot;Inspire&quot; both land on the kanban. See <a href="/guide/command-palette.html">Sidebar &amp; ⌘K</a> for the full tour.</p><h2 id="getting-into-the-studio" tabindex="-1">Getting into the Studio <a class="header-anchor" href="#getting-into-the-studio" aria-label="Permalink to &quot;Getting into the Studio&quot;">​</a></h2><p>Once you&#39;re signed in, the sidebar gives you everything:</p><ul><li><strong>Channel selector</strong> in the Studio section — switch channels, or create your first one.</li><li><strong>Studio links</strong> — Episodes, Proposals, Discover, Scripts, Storyboard, Composition, Audio, Publish.</li><li><strong>⌘K</strong> — search and navigate everything without leaving the keyboard.</li></ul><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Every signed-in account gets a free model for script writing — no key required. Add a Gemini or Claude key (Profile → API keys) to unlock those providers.</p></div><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/guide/command-palette.html">Sidebar &amp; ⌘K</a> — the shortest tour of the layout</li><li><a href="/guide/channels.html">Channels</a> — create your first channel</li><li><a href="/guide/episodes.html">Episodes</a> — your single backlog and pipeline</li><li><a href="/guide/proposals.html">Proposals</a> — AI brainstorms your next episode</li></ul>',10))])}const b=a(l,[["render",d]]);export{f as __pageData,b as default};
